/// <summary>
/// Checks if site exists or not.
/// </summary>
/// <param name = "_siteId">Site Id.</param>
/// <returns>True if exists; otherwise, false.</returns>
public static boolean isCSite(InventSiteId _siteId)
{
    return (select firstonly RecId from METSiteControllingAndSubOrdinateSetup
                where METSiteControllingAndSubOrdinateSetup.SiteId == _siteId).RecId != 0;
}

/// <summary>
/// METSiteControllingAndSubOrdinateSetup Modified field
/// </summary>
/// <param name = "_fieldId">FieldId</param>
public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch(_fieldId)
    {
        case fieldNum(METSiteControllingAndSubOrdinateSetup, IsControllingSite):
            this.ControllingSiteId = '';
            break;

        case fieldNum(METSIteControllingAndSubOrdinateSetup, SiteId):
            this.State = this.getStateForInventSitePrimaryAddress();
            break;

        case fieldNum(METSiteControllingAndSubOrdinateSetup, ControllingSiteId):
            if (this.ControllingSiteId)
            {
                this.IsControllingSite = NoYes::No;
            }
            break;

    }
}

/// <summary>
/// Exists by site
/// </summary>
/// <param name = "_inventSiteId">Invent SiteId</param>
/// <returns>true or false</returns>
static boolean existBySite(InventSiteId  _inventSiteId)
{
    if (!_inventSiteId)
    {
        return false;
    }

    return (select firstonly RecId from metSiteControllingAndSubOrdinateSetup
                index hint SiteIdx
                where metSiteControllingAndSubOrdinateSetup.SiteId == _inventSiteId).RecId != 0;
}

/// <summary>
/// Finds and returns <c>METSiteControllingAndSubOrdinateSetup</c>.
/// </summary>
/// <param name = "_siteId">Site Id.</param>
/// <param name = "_forUpdate">If record is selected for update.</param>
/// <returns><c>METSiteControllingAndSubOrdinateSetup</c> record.</returns>
public static METSiteControllingAndSubOrdinateSetup findBySite(InventSiteId _siteId, boolean _forUpdate = false)
{
    METSiteControllingAndSubOrdinateSetup siteControllingAndSubOrdinateSetup;

    siteControllingAndSubOrdinateSetup.selectForUpdate(_forUpdate);

    select firstonly siteControllingAndSubOrdinateSetup
        where siteControllingAndSubOrdinateSetup.SiteId == _siteId;

    return siteControllingAndSubOrdinateSetup;
}

/// <summary>
/// Get state of invent site id primary address
/// </summary>
/// <returns>Site primary address State</returns>
public LogisticsAddressStateId getStateForInventSitePrimaryAddress()
{
    LogisticsPostalAddress postalAddress;
    LogisticsLocation      logisticsLocation;
    InventSiteLogisticsLocation inventSiteLogisticsLocation;
    InventSite              inventSite;

    select firstonly State from postalAddress
        exists join logisticsLocation
            where logisticsLocation.RecId == postalAddress.Location
            && postalAddress.ValidFrom <=  DateTimeUtil::getSystemDateTime()
            && postalAddress.ValidTo >= DateTimeUtil::getSystemDateTime()
         exists join inventSiteLogisticsLocation
            where logisticsLocation.RecId == inventSiteLogisticsLocation.Location
         exists join inventSite
            where inventSiteLogisticsLocation.Site == inventSite.RecId
            && inventSiteLogisticsLocation.IsPrimary == NoYes::Yes
            && inventSite.SiteId == this.SiteId;

    return postalAddress.State;

}

/// <summary>
/// Finds and returns controlling site setup record.
/// </summary>
/// <param name = "_stateId">State.</param>
/// <param name = "_forUpdate">If record is selected for update.</param>
/// <returns><c>METSiteControllingAndSubOrdinateSetup</c> record.</returns>
public static METSiteControllingAndSubOrdinateSetup findControllingSiteId(LogisticsAddressStateId _stateId,  boolean _forUpdate = false)
{
    METSiteControllingAndSubOrdinateSetup siteControllingAndSubOrdinateSetup;

    siteControllingAndSubOrdinateSetup.selectForUpdate(_forUpdate);

    select firstonly siteControllingAndSubOrdinateSetup
        where siteControllingAndSubOrdinateSetup.State == _stateId
        &&    siteControllingAndSubOrdinateSetup.IsControllingSite == NoYes::Yes; 

    return siteControllingAndSubOrdinateSetup;
}

/// <summary>
/// Gets controlling site setup record.
/// </summary>
/// <returns><c>METSiteControllingAndSubOrdinateSetup</c> record.</returns>
public METSiteControllingAndSubOrdinateSetup controllingSiteSetup()
{
    return METSiteControllingAndSubOrdinateSetup::findControllingSiteId(this.State);
}

/// <summary>
/// Validate mandatory cases
/// </summary>
/// <returns>True or false</returns>
public boolean validateWrite()
{
    boolean ret;

    ret = super();

    if (ret)
    {
        if (!this.ControllingSiteId && !this.IsControllingSite)
        {
            ret = checkFailed("Site can be either controlling or subordinate site. Please fill the controlling site or set if it is iscontrolling Site");
        }
    }

    return ret;
}
